-- ============================================================
-- DB 타임존 KST 전환 - 기존 UTC 데이터 +9h 보정 (tz-kst-cutover-1)
-- 생성일: 2026-08-30 / 런북: .claude/refs/DB타임존_KST전환_런북_2026-08-30.md
--
-- ★실행 전제(런북 §3 순서 엄수):
--   1) RDS 수동 스냅샷 생성 완료
--   2) 백엔드 앱 정지 상태
--   3) RDS 파라미터 그룹 time_zone=Asia/Seoul 적용 후 "새" Workbench 세션에서 실행
--   4) 아래 @CUTOVER_UTC 를 실제 값으로 교체했는지 확인
--
-- ★@CUTOVER_UTC = 운영 이관(개발 덤프 로드) 시점의 "UTC 벽시계".
--   AWS 콘솔 > RDS > prafta-db > 생성 시각(UTC)으로 확인해 기입한다.
--   이 시각 이후 벽시계의 행(=운영 라이브에서 NOW()/UTC 로 기록된 행)만 +9h 보정한다.
--   이전 행은 개발 DB(KST) 덤프 이식분이라 이미 KST — 보정 대상 아님.
--   (그레이존: 이관 직전 9시간 내 개발 기록 행은 +9h 과보정될 수 있으나 전부
--    실고객 이전 테스트 데이터라 수용 — 런북 §5)
--
-- ★보정 제외 컬럼(Java-KST 기록 - 절대 밀지 말 것, 본 파일에 미포함 확인됨):
--   tb_near_miss.OCCUR_DTIME / tb_cmpny_share_snapshot_nearmiss.OCCUR_DTIME
--
-- ★1회만 실행. 아래 마커 INSERT 가 중복 키로 실패하면 이미 실행된 것 - 전체 중단하라.
-- ============================================================

SET SQL_SAFE_UPDATES = 0;

-- 이중 실행 가드 마커(재실행 시 Duplicate entry 오류로 정지)
CREATE TABLE IF NOT EXISTS tz_migration_marker (
  STEP        varchar(100) NOT NULL COMMENT '마이그레이션 단계 식별자',
  EXECUTED_AT datetime     NOT NULL COMMENT '실행 시각(KST - 전환 후 실행되므로)',
  PRIMARY KEY (STEP)
) COMMENT='DB 타임존 KST 전환 마이그레이션 실행 마커';

-- ★★ 확정값 기입 완료(2026-08-30): RDS prafta-db 생성 시각 = 2026-07-18 11:14 KST = 02:14 UTC
--    (콘솔 실측 — 이 시각 이후 벽시계 행만 운영 라이브(UTC 기록)이므로 +9h 보정 대상)
SET @CUTOVER_UTC = '2026-07-18 02:14:00';

-- 가드 1: 플레이스홀더 미교체 차단 - 미교체 상태면 다중행 서브쿼리 오류(1242)로 즉시 정지된다.
--         (Workbench 기본 동작 = 오류 시 스크립트 중단. "계속 실행" 옵션을 켜지 말 것)
SELECT IF(@CUTOVER_UTC LIKE '{{%', (SELECT 1 UNION ALL SELECT 2), 1) AS placeholder_guard;

-- 가드 2: 유효한 DATETIME 인지 확인 - 파싱 불가 값이면 NULL 이 되어 아래 서브쿼리 오류로 정지.
SELECT IF(CAST(@CUTOVER_UTC AS DATETIME) IS NULL, (SELECT 1 UNION ALL SELECT 2), 1) AS datetime_guard;

START TRANSACTION;

-- 이중 실행 가드 마커: 재실행 시 Duplicate entry 오류로 정지.
--   트랜잭션 안에서 INSERT 하므로, 아래 UPDATE 도중 실패해 롤백되면 마커도 함께 사라져 재실행이 가능하다.
INSERT INTO tz_migration_marker (STEP, EXECUTED_AT) VALUES ('tz-kst-cutover-1-shift', NOW());

