-- [security Medium #2] SMS_VERIFIED_AT 은 2026-08-30 CONVERT_TZ 수정 배포 이후부터 "이미 KST"로 적재된다.
--   그런 행(같은 행의 ACCESS_DTIME(UTC)보다 약 +9h 큼)을 또 밀면 이중 밀림이므로,
--   UTC 로 적재된 행(인증시각이 열람시각 이전 ±1h 이내)만 보정한다. 이미 KST 인 행은 제외.
UPDATE tb_location_access_log SET SMS_VERIFIED_AT = SMS_VERIFIED_AT + INTERVAL 9 HOUR WHERE SMS_VERIFIED_AT IS NOT NULL AND SMS_VERIFIED_AT >= @CUTOVER_UTC AND SMS_VERIFIED_AT < ACCESS_DTIME + INTERVAL 1 HOUR;
