-- ============================================================
-- 사후 검증 (런북 §6-B) - 아래 결과를 기대값과 대조할 것
-- ============================================================
-- 1) NOW() 가 KST 인지 (현재 한국 시각과 일치해야 함)
SELECT @@session.time_zone AS sessTz, DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i') AS nowWall;

-- 2) 표본: TBM 테스트 세션 - 기대값 endedWall = '2026-08-30 10:49'
SELECT SESSION_CD, DATE_FORMAT(ENDED_AT, '%Y-%m-%d %H:%i') AS endedWall
FROM tb_tbm_session WHERE SESSION_CD = 'T202608300001022';

-- 3) 표본: 최근 출근(08-30) - 기대값 insWall = '2026-08-30 10:05' (CHECK_IN 1005 와 일치)
SELECT ATTD_ID, CHECK_IN_TIME, DATE_FORMAT(INSERT_DATE, '%Y-%m-%d %H:%i') AS insWall
FROM tb_user_attd_mgmt WHERE ATTD_ID = '2026083000061';

-- 4) 미래 시각 이상치(보정 이중 적용 의심 신호) - grantExpire 는 연차 만료예정이라 미래가 정상, 그 외 0 이어야 함
SELECT
 (SELECT COUNT(*) FROM tb_user_attd_mgmt   WHERE INSERT_DATE > NOW() + INTERVAL 5 MINUTE) AS attdFuture,
 (SELECT COUNT(*) FROM tb_tbm_session      WHERE INSERT_DATE > NOW() + INTERVAL 5 MINUTE) AS tbmFuture,
 (SELECT COUNT(*) FROM tb_user             WHERE INSERT_DATE > NOW() + INTERVAL 5 MINUTE) AS userFuture,
 (SELECT COUNT(*) FROM tb_user_work_plan   WHERE INSERT_DATE > NOW() + INTERVAL 5 MINUTE) AS planFuture;

-- 5) 행수 불변 확인(보정은 UPDATE 만 - 개수 변화가 있으면 이상)
SELECT
 (SELECT COUNT(*) FROM tb_user_work_plan) AS planCnt,
 (SELECT COUNT(*) FROM tb_user_attd_mgmt) AS attdCnt,
 (SELECT COUNT(*) FROM tb_auth_token)     AS tokenCnt;
